 LiveGiftExperience(Activity a,Send send){activity=a;sender=send;ui=new CommerceUi(a);android.content.SharedPreferences prefs=a.getSharedPreferences("live-gifts",0);soundOn=prefs.getBoolean("sound",true);reduceEffects=prefs.getBoolean("reduce_effects",false);allowed.addAll(Arrays.asList("rose","star","crown"));comboable.addAll(Arrays.asList("rose","star","crown","aurora","meteor","butterfly","lotus","car"));sounds=new SoundPool.Builder().setMaxStreams(4).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()).build();sounds.setOnLoadCompleteListener((pool,id,status)->{if(status==0)loaded.add(id);});for(String[] gift:GIFTS)try{String path="gifts/"+gift[0]+".wav";int id;try(android.content.res.AssetFileDescriptor fd=a.getAssets().openFd(path)){id=sounds.load(fd,1);}catch(IOException compressed){File file=new File(a.getCacheDir(),"gift-"+gift[0]+".wav");try(InputStream in=a.getAssets().open(path);OutputStream out=new FileOutputStream(file)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}id=sounds.load(file.getAbsolutePath(),1);}samples.put(gift[0],id);}catch(IOException ignored){}for(String extra:new String[]{"car_intro","car_engine","yacht_waves","yacht_horn","castle_intro","castle_impact","castle_fanfare"})try{String path="gifts/"+extra+".wav";int id;try(android.content.res.AssetFileDescriptor fd=a.getAssets().openFd(path)){id=sounds.load(fd,1);}catch(IOException compressed){File file=new File(a.getCacheDir(),"gift-"+extra+".wav");try(InputStream in=a.getAssets().open(path);OutputStream out=new FileOutputStream(file)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}id=sounds.load(file.getAbsolutePath(),1);}samples.put(extra,id);}catch(IOException ignored){} }
