 void setTargets(JSONArray participants,String hostId,String hostName){stageTargets=participants!=null?participants:new JSONArray();if(targetUserId.isEmpty()&&hostId!=null){targetUserId=hostId;targetUserName=hostName!=null?hostName:"";}}
 void configure(JSONObject catalog){if(catalog==null)return;enabled=catalog.optBoolean("enabled",false)&&catalog.optBoolean("experience",false);priceVersion=catalog.optInt("version");balance=catalog.optLong("balance");stock.clear();JSONArray inventory=catalog.optJSONArray("inventory");for(int n=0;inventory!=null&&n<inventory.length();n++){JSONObject item=inventory.optJSONObject(n);if(item!=null)stock.put(item.optString("giftId"),item.optInt("quantity"));}allowed.clear();costs.clear();tiers.clear();comboable.clear();JSONArray items=catalog.optJSONArray("items");for(int i=0;items!=null&&i<items.length();i++){JSONObject item=items.optJSONObject(i);String id=item==null?"":item.optString("id");if(item!=null&&name(id)!=null&&item.optInt("costCoins")>0){allowed.add(id);costs.put(id,item.optInt("costCoins"));tiers.put(id,item.optString("tier","small"));if(item.optBoolean("comboable",!id.equals("yacht")&&!id.equals("castle")))comboable.add(id);}}}
 void receipt(JSONObject value){balance=value.optLong("balance",balance);if(value.optJSONObject("catalog")!=null)configure(value.optJSONObject("catalog"));if(balanceLabel!=null)balanceLabel.setText(I18n.t("Xu tặng")+" · "+number(balance));}
 private String number(long n){return java.text.NumberFormat.getIntegerInstance(new java.util.Locale("vi","VN")).format(n);}
 void open(){if(loading||(dialog!=null&&dialog.isShowing()))return;loading=true;NativeApi.shared.call("GET","/api/live/gifts",null,(data,error,status)->{loading=false;if(closed||activity.isFinishing())return;if(error!=null){Toast.makeText(activity,I18n.t("Chưa tải được quà. Thử lại sau."),Toast.LENGTH_SHORT).show();return;}configure(data);showPicker();});}
